INSERT INTO `about_us_technologies` (`id`, `heading`, `content`, `created_at`, `updated_at`) VALUES
(1,	'Advanced Audio Technology Education',	'<div class=\"row\">\n                <div class=\"col-md-12 col-12 pt-3\">\n                    <div class=\"font-regular text-grey2 font-13\">\n                        Advances in Audio technology has evolved in the music industry and Crypto Cipher is dedicated to educating Musicians, Composers , Music Students and Music Aspirants on latest trends in audio technology and their applications through its various advanced education programmes in line with the education system of India. Crypto Cipher seeks to develop interest, capacity and expertise in the use of latest audio technology tools by Sound Engineers, Musicians and Students.\n                    </div>\n                </div>\n                <div class=\"col-md-6 col-12 pt-3\">\n                    <div class=\"font-regular text-grey2 font-13\">\n                        Crypto Cipher Mission is provide most advance audio technology education in India. Making our student powerhouse of knowledge by giving them most involving & informative process, finally developing an audio researching attitude in their practice.<br><br>\n                        This proven process develops most fundamental concepts strong to stay updated with ever evolving Audio Technology. This one complete process is developed & trained by Industry  successful experts with international standards of course structure for most rewarding career in the field of audio.<br><br>\n                        Crypto Cipher Audio Lab Provides you with sound proof classrooms for theory sessions & all practical sessions will be done inside the professional studio. A separate control room & recording studio set is just dedicated for student practice so that they do enough practice before they enter professional industry. Candidate after completing the Sound Engineering Diploma will be able to work in studio with all digital technologies related to music production and also will be able to construct complete professional studio single handily.\n                    </div>\n                </div>\n                <div class=\"col-md-6 col-12 pt-3\">\n                    <div class=\"font-regular text-grey2 font-13\">\n                        Crypto Cipher Future Vision, plans to launch India’s first Audio Research library where all our student after classes can practice endlessly in a library environment under various knowledgeable mentors trained in D.A.W ( Logic Pro X, Ableton Live, Fruity Loops etc ), Audio Electronics, Acoustics, EDM, Acoustics and various audio technology Dimensions.<br><br>\n                        Crypto Cipher also has vision of developing a professional career for students under same roof by giving ample career Opportunities by developing a separate professional studio where industry commercial work will be offered to students. Students will get chance of working with clients under guidance of studio experts before they enter professional industry creating a strong portfolio beforehand. \n                    </div>\n                </div>\n            </div>',	NULL,	NULL);
INSERT INTO `academy_courses` (`id`, `image`, `heading`, `content`, `url`, `created_at`, `updated_at`) VALUES
(1,	'course.svg',	'Best Music Production Courses in Delhi | Crypto Cipher®',	'<div><b><font color=\"#397b21\">Music Production Course (3 Months Short-Term Professional Program)</font></b></div><div><br></div><div>Perfect for: Musicians, Working Professionals &amp; Serious Beginners with a Tight Schedule</div><div>Format: Alternate Days | 2–4 Hours per Session</div><div><br></div><div><b>📌 Highlights:</b></div><div><br></div><ul><li>Advanced-level foundation course crafted for those serious about launching a professional music career</li><li>Ideal for musicians, artists, and working professionals who cannot commit to long-term programs but want intensive, career-focused training</li><li>Covers Advanced Logic Pro X, Ableton Live, and Foundational Mixing Techniques—tools and skills essential in the professional music industry</li><li>Delivered by a team of specialised faculty with real-world music production experience</li><li>Highly structured lectures that extend beyond the official 2-hour duration for in-depth topic coverage</li><li>Learn industry-grade music production workflows and develop your creative process from day one</li><li>Includes Crypto Cipher Music Production Certification after final examination</li><li>Designed to equip you with a solid technical and creative base for future advanced studies or professional work</li><li>One of the Best Short-Term Music Production Courses in Delhi – Flexible, Intensive &amp; Career-Oriented</li></ul><div><b><font color=\"#397b21\">Course Fee: ₹60,000 + GST</font></b></div>',	'/music-production-course',	'2021-01-18 10:58:05',	'2025-05-21 18:52:21'),
(3,	'course.svg',	'Best Music Production Diploma Course ( Delhi, India )  | Crypto Cipher®',	'<div><b style=\"white-space-collapse: preserve; color: rgb(57, 123, 33); font-family: Arial;\">Music Production Diploma (8 Months &amp; 2 Months Project Submission)</b></div><div><font face=\"Arial\" color=\"#397b21\"><span style=\"white-space-collapse: preserve;\"><b><br></b></span></font></div><ul><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Perfect for: Aspiring Musicians &amp; Creators Seeking a Complete Music Production Journey</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Format: 2–4 Hours Per Lecture | Project-Based Learning</span></font></li></ul><div><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\"><b>📌 Highlights:</b></span></font></div><ul><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">A comprehensive, full-cycle music production course built for aspiring musicians and producers in India</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Perfect for students who want to learn end-to-end music production at a highly affordable fee without compromising on international education standards</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Carefully designed to provide a global-quality education within a course framework that aligns with Indian learning environments and budgets</span></font></li></ul><div><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\"><b>Covers the complete production journey:</b></span></font></div><ul><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">&nbsp;Advanced Logic Pro X</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">&nbsp;Ableton Live</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">&nbsp;Music Theory</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">&nbsp;Vocal Processing</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">&nbsp;Sound Design &amp; Synthesis</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">&nbsp;Mixing &amp; Mastering</span></font></li></ul><div><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\"><b><br></b></span></font></div><ul><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Delivered by specialised industry faculty offering deep insights into real-world music production techniques</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Classes extend beyond standard hours to ensure clarity and creative depth in every topic</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Includes 2-months guided project submission to apply everything you learn in a real-world production scenario</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Structured curriculum with lectures, assignments, practical evaluations, and mentorship</span></font></li><li><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\">Students receive an industry-recognized Crypto Cipher Music Production Diploma Certification</span></font></li></ul><div><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\"><b>Best Music Production Diploma Course in India – Affordable, Complete, and Aligned with Global Standards</b></span></font></div><div><font face=\"Arial\"><span style=\"white-space-collapse: preserve;\"><b><br></b></span></font></div><div><span style=\"white-space-collapse: preserve; font-family: Arial;\"><b><font color=\"#397b21\">Course Fee: ₹1,10,000 + GST</font></b></span></div>',	'/music-production-diploma-course',	'2025-01-18 10:58:05',	'2025-05-26 01:47:57'),
(4,	'mix.svg',	'Sound Engineering Diploma : Advanced Music Production & Audio Engineering Course',	'<div><b><font color=\"#397b21\">Advanced Music Production &amp; Sound Engineering Diploma (1-Year Professional Program + 2 months project submission )</font></b></div><div><br></div><div>Perfect for: Serious Learners Aiming for a Full-Fledged Career in Music &amp; Audio Engineering</div><div>Format: Alternate Days Immersive Lectures , Final 2-Month Project</div><div><b><br></b></div><div><b>📌 Highlights:</b></div><div><br></div><ul><li>This is not just a course—it\'s a career-defining, step-by-step training journey designed to transform you into a versatile “One-Man Army” in the world of audio and music production</li><li>Ideal for students who aspire to become self-reliant audio professionals capable of handling every aspect of a professional studio environment—from creative production to complex technical management</li></ul><div><b>Learn to independently manage projects with expertise in:</b></div><ul><li>&nbsp;Studio Soundproofing &amp; Acoustics</li><li>&nbsp;Recording Techniques &amp; Signal Flow</li><li>&nbsp;Recordings for Films , Interviews &amp; Location Sound</li><li>&nbsp;All Post Production Work</li><li>&nbsp;Mixing &amp; Mastering like Industry Pros</li><li>&nbsp;Deep Music Theory &amp; Song Arrangements</li><li>&nbsp;Film Scoring ,Foley &amp; Dubbing</li><li>&nbsp;Bollywood Music arrangements, EDM &amp; Orchestral arrangements using advanced Midi techniques</li><li>&nbsp;Advanced Logic Pro X &amp; Ableton Live</li><li>&nbsp;Studio Interconnections, Troubleshooting &amp; Cable Management</li><li>&nbsp;Understanding Audio Unit Measurements &amp; Studio Equipment Operation</li><li>Covers everything from arranging and producing music to fixing cables, ensuring you\'re never dependent on others for your studio workflow</li><li>Gain hands-on experience with industry-standard equipment, real-time troubleshooting, and practical exercises for every module</li><li>Includes workshops, home exercises, practical labs, and deep mentorship throughout the course duration</li><li>Final 2-month capstone project to showcase your full capability as a professional</li><li>Earn a prestigious Crypto Cipher Advanced Diploma Certification in Music Production &amp; Sound Engineering upon completion</li></ul><div><br></div><div><b>Best 1-Year Advanced Diploma Course in India – Designed for Long-Term Success &amp; Complete Studio Mastery</b></div><div><br></div><div><b>Career Opportunities Beyond Just Music Production:</b></div><ul><li>Music Producer</li><li>Mixing &amp; Mastering Engineer</li><li>Recording Engineer</li><li>Studio Manager or Consultant</li><li>Audio Equipment &amp; Acoustic Design Specialist</li><li>Live Sound Engineer</li><li>Sound Designer for Film, TV, &amp; Games</li><li>Freelance Studio Troubleshooter / Technical Consultant</li></ul><p><b><font color=\"#397b21\">Course Fee: ₹1,80,000 + GST</font></b></p>',	'/sound-engineering-course',	'2021-01-18 10:58:05',	'2026-03-04 18:21:04'),
(5,	'1904879652.svg',	'Live Sound Engineering Course in Delhi, India | Crypto Cipher®',	'<p><font color=\"#397b21\"><b>Live Sound Engineering in Delhi,India (4 Months Duration )</b></font></p><p>Format: 3–4 Hours Per Lecture | Thrice a week | Project-Based professional Learning</p><p>📌 Highlights:</p><ul><li>Structured Learning Pathway: A progressive journey from sound fundamentals and electronics to advanced system tuning and live troubleshooting.</li><li>Industry-Relevant Modules: Covers all core areas including analog/digital console workflows, RF systems, PA tuning, mixing strategies, and real-world application.</li><li>Hands-on Training: Emphasis on practical experience with professional-grade audio gear and live event simulations.</li><li>In-depth Technical Proficiency: Gain mastery over mixing consoles, signal flow, gain staging, microphone techniques, wireless coordination, and more.</li><li>Professional Workflow Development: Learn to read technical riders, patch systems, handle on-the-fly issues, and coordinate with artists and crew.</li><li>Tools and Software Integration: Includes training with measurement tools like <b>Arraycalc</b>, <b>Mapp3D</b>, <b>Venuesynthesis</b>, <b>offline editors for professional consoles</b>, <b>SMAART®</b> and <b>Room EQ Wizard</b> for real-time system tuning.</li><li>Career-Focused Preparation: Aligned to industry roles such as FOH Engineer, Monitor Engineer, System Technician, Application Specialist, Product Demonstration, Audio Installation and Playback Engineer.</li></ul><p>Delivered by specialised industry faculty offering deep insights into real-world Live Sound Engineering</p><ul><li>Classes extend beyond standard hours to ensure clarity and creative depth in every topic</li><li>Includes 1-months guided project submission to apply everything you learn in a real-world production scenario</li><li>Structured curriculum with lectures, assignments, practical evaluations, and mentorship</li><li>Students receive an industry-recognized Crypto Cipher® Live Sound Engineering Certification</li></ul><p>Best Live Sound Engineering Course in India – Affordable, Complete, and Aligned with Global Standards</p><p><font color=\"#397b21\"><b>Course Fee: ₹1,10,000 + GST</b></font></p>',	'/live-sound-engineering-course',	'2025-05-26 01:57:57',	'2026-02-15 18:11:58');
