INSERT INTO `downloads` (`id`, `name`, `content`, `file`, `path`, `created_at`, `updated_at`, `sort_by`) VALUES
(7,	'Crypto Cipher Drum And Percussion Maker: Free Preset and Sample Pack',	'<p><b>Ableton Instrument Rack Preset and Sample Pack. Please read full tutorial on this <a href=\"https://www.cryptocipheracademy.com/newsroom/Creative_Drum_And_Percussion_Sound_Design_With_Ableton_Simpler\">link - ( Click Me )</a></b></p>',	'<p><b><br></b></p><blockquote><b>Crypto Cipher</b>\'s Drum And Percussion Maker: Free Preset and Sample Pack contains an Ableton Instrument Rack preset for making drums and percussion from foley sounds and field recordings along with a Sample Pack with 57 one shot samples of drum and percussion samples created using the preset.</blockquote>',	'CryptoCipherPercussionMaker.zip',	'2022-07-24 06:00:20',	'2022-07-24 15:54:43',	NULL),
(8,	'Crypto Cipher Academy_Lofi Beat Tutorial: Ableton Project',	'<span class=\"\">Ableton Live Project (.alp). Please read full tutorial on this</span>\r\n<a href=\"https://www.cryptocipheracademy.com/newsroom/How_To_Make_A_Lofi_Hip_Hop_Beat_6_Easy_Steps\">link - (Click Me)</a>',	'<div><b>Crypto Cipher</b> Academy\'s Ableton Project with a Lofi Hip Hop Beat to serve as an example for beginners.</div>',	'Crypto Cipher Academy_Lofi Beat Tutorial.zip',	'2022-09-05 19:31:15',	'2022-09-05 19:34:04',	NULL),
(9,	'Crypto Cipher Academy_Melodic Trap Beat Tutorial: Ableton Project',	'<p><span class=\"\">Ableton Live Project (.alp). Please read full tutorial (Part 1 of 3) on this</span>&nbsp;<a href=\"https://www.cryptocipheracademy.com/newsroom/How_to_Make_Melodic_Trap_Beats_Part_1_Drums\" target=\"_blank\">link. (Click Me)</a><br></p>',	'<p><b>Crypto Cipher</b>&nbsp;Academy\'s Ableton Project with a Melodic Trap Beat to serve as an example for beginners.<br></p>',	'140_Em_Melodic Trap Beat_CCA .zip',	'2022-11-04 20:16:14',	'2022-11-04 20:24:44',	NULL);
