INSERT INTO `students_works` (`id`, `year`, `name`, `speciality`, `image`, `short_desc`, `student_profile`, `education`, `interest`, `work_prof`, `testimonial`, `status`, `created_at`, `updated_at`, `slug`, `meta_title`, `meta_keyword`, `meta_description`, `sort_by`) VALUES
(1,	'2018',	'Manya Narang',	'Bollywood Playback Singer | Music Producer | Sound Engineer | Indian Idol Contestant',	'991097626.jpg',	'<p><b>Manya Narang</b> enrolled in <b>Sound Engineering Diploma in 2018</b> and now working as a professional Mixing &amp; Mastering Engineer. She also deliver full track projects in her own newly set up studio with the name \" Studio Mousse \" in New Delhi.</p><p><strong data-start=\"251\" data-end=\"267\">Manya Narang</strong>&nbsp;is a multifaceted Indian artist renowned for her prowess as a singer, composer, performer, music producer, and sound engineer.&nbsp;<span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">She gained national recognition as one of the Top 8 finalists in&nbsp;<em data-start=\"65\" data-end=\"87\">Indian Idol Season 9</em>.</span>&nbsp;<span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Since then, she has graced stages worldwide, performing in over 50 countries, including iconic venues like The Wembley and O2 Arena.</span><br></p><p data-start=\"547\" data-end=\"663\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">In 2018, Manya pursued her passion for music technology by enrolling in a Sound Engineering Diploma, subsequently establishing herself as a professional Mixing &amp; Mastering Engineer.</span>&nbsp;<span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Her technical acumen complements her artistic endeavors, allowing her to produce and refine music with precision.</span></p><p data-start=\"665\" data-end=\"823\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Manya has shared the stage with legendary artists such as Sonu Nigam, Salim–Sulaiman, Anu Malik, Lakhwinder Wadali, and Kamal Khan.</span>&nbsp;<span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Her collaborations and performances have solidified her reputation in the Bollywood music scene</span></p>',	'<p><iframe width=\"100%\" height=\"315\" src=\"https://www.youtube.com/embed/VEc_PJPbjOQ?si=b9FOHluhSUGsw4V7\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen=\"\"></iframe></p>\r\n\r\n\r\n<p><iframe width=\"100%\" height=\"315\" src=\"https://www.youtube.com/embed/EoU7n2tiCG8?si=_6yuhHMzvOofHL7Y\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen=\"\"></iframe></p>\r\n\r\n\r\n\r\n<p><iframe width=\"100%\" height=\"315\" src=\"https://www.youtube.com/embed/uYItecMpQHQ?si=cPHxO-mHKGHQ9uwF\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen=\"\"></iframe></p>\r\n\r\n\r\n\r\n<p><iframe width=\"100%\" height=\"315\" src=\"https://www.youtube.com/embed/c7G5wHgP9QU\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"\"></iframe></p>\r\n\r\n<p><iframe width=\"100%\" height=\"315\" src=\"https://www.youtube.com/embed/6nUVlCTmvMI\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"\"></iframe></p>\r\n\r\n<p><iframe width=\"100%\" height=\"315\" src=\"https://www.youtube.com/embed/zhdOzxSykHc\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"\"></iframe></p>',	NULL,	NULL,	NULL,	'<p>\r\n<iframe width=\"100%\" height=\"360\" src=\"https://www.youtube.com/embed/C3eDboXMYgQ\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"\"></iframe>\r\n<br></p><p><img src=\"data:image/png;base64,\" data-filename=\"download (1).png\" style=\"width: 100%;\"><br></p>',	'1',	'2021-04-14 04:40:21',	'2025-06-04 19:38:50',	'manya-narang',	'Manya Narang – Indian Idol Finalist, Global Performer & Sound Engineer',	'Discover Manya Narang, Top 8 finalist of Indian Idol Season 9, acclaimed singer, composer, and professional sound engineer. Performing globally with icons like Sonu Nigam and Salim–Sulaiman.',	'<p><b>Discover Manya Narang, Top 8 finalist of Indian Idol Season 9, acclaimed singer, composer, and professional sound engineer. Performing globally with icons like Sonu Nigam and Salim–Sulaiman.</b></p>',	1.00),
(2,	'2016',	'Gurpreet BMP',	'Punjabi Film Composer | Music Arranger | Mixing Engineer | Working as Successful Music Producer ( Mohali, Punjab)',	'454267007.png',	'<p data-start=\"178\" data-end=\"419\"><strong data-start=\"178\" data-end=\"194\">Gurpreet BMP</strong>&nbsp;enrolled in the Music Production course at Crypto Cipher Academy in 2016 and has since built a thriving career in the Indian music industry. He is the founder of&nbsp;<strong data-start=\"357\" data-end=\"372\">BMP RECORDS</strong>, a full-fledged music studio and record label.</p><p data-start=\"421\" data-end=\"655\">As a successful YouTube artist with&nbsp;<strong data-start=\"457\" data-end=\"492\">millions of views and followers</strong>, Gurpreet is known for his distinctive sound and high-quality music productions. His notable work includes composing for the Punjabi feature film&nbsp;<em data-start=\"639\" data-end=\"654\"><b>Jatta Doli Na</b></em>.</p><ul data-start=\"684\" data-end=\"804\">\r\n<li data-start=\"684\" data-end=\"704\">\r\n<p data-start=\"686\" data-end=\"704\"><strong data-start=\"686\" data-end=\"702\">Daler Mehndi,&nbsp;</strong><strong data-start=\"707\" data-end=\"725\">Nachhatar Gill,&nbsp;</strong><strong data-start=\"730\" data-end=\"744\">Feroz Khan,&nbsp;</strong><strong data-start=\"749\" data-end=\"766\">Roshan Prince,&nbsp;</strong><strong data-start=\"771\" data-end=\"787\">Shipra Goyal</strong> and many others.</p></li>\r\n</ul><p>\r\n\r\n\r\n\r\n</p><p data-start=\"806\" data-end=\"926\">Gurpreet BMP continues to leave a strong mark on the Punjabi music scene with original releases and star collaborations.</p>',	'<p></p>\r\n\r\n<p><iframe width=\"100%\" height=\"315\" src=\"https://www.youtube.com/embed/CbY5W875S0E?si=nGKoH-tjNneIO69E\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen=\