INSERT INTO `vacancies` (`id`, `title`, `description`, `created_at`, `updated_at`) VALUES
(1,	'Exclusive job opportunity for Crypto Cipher students',	'<p><b>MUSIC ANNOTATION INTERNS (REMOTE)</b> - Paid Exclusive Internship / Live Project with a Global Musical MNC</p><h6><b>Straive</b>, in partnership with <b>Crypto Cipher</b>, is offering an exclusive job opportunity for Crypto Cipher students.<br>Music Annotation Intern – Live Project with a Global Musical MN<br>₹300 per hour<br>Full-Time (8 hrs) / Part-Time (Min 4 hrs) , Remote Work<br><b>Core Task:<br></b>High-precision labeling of genre, mood, instrumentation, and tempo for a global music catalog.<br>Requirement : Must complete at least 4 units per hour to be eligible for remuneration.<br>Skills: Strong foundation in music theory and a sharp ear for detail<br>Send your CV ASAP to: academy@cryptocipher.in</h6>',	'2026-02-17 21:28:31',	'2026-02-17 21:31:15'),
(2,	'Sound Engineering Paid Internship for Crypto Cipher Students -Studio ASAP ( Dwarka, Delhi )',	'<h6><b><br></b></h6><h6><b>Send your CV to: academy@cryptocipher.in</b></h6><pre><b>THE HIRING PROCESS</b><br><pre>&nbsp;Selection Round<br>• 1-Week Hiring Window<br>• 2 Rounds of Physical Interviews at Dwarka Studio<br><b>Internship Period (6–8 Weeks)</b><br>• Intensive practical training<br>• ₹10,000 – ₹12,000 Stipend (for 4 weeks)<br><b>Final Review &amp; Full-Time Offer</b><br>• Performance review at end of internship<br>• Selected interns will receive a formal full-time job offer</pre><pre><b>REQUIREMENTS</b><br>• Strong fundamentals in audio engineering &amp; acoustics<br>• Clear understanding of signal flow<br>• Familiarity with digital mixing consoles<br>• Serious, disciplined &amp; highly driven mindset<br></pre><pre><b>WHAT YOU WILL LEARN</b></pre><pre><b>Industry-Standard Software Training</b><br>Hands-on experience with:<br>• L-Acoustics Soundvision<br>• JBL Venue Synthesis<br>• EASE Focus 3<br><b>Large-Scale Audio System Design</b><br>• Arena &amp; Stadium show planning<br>• Private concerts &amp; exhibitions<br>• High-end corporate &amp; car launches<br>• Permanent installation planning<br>• Acoustic simulation &amp; heat mapping<br>&nbsp;<b>Live Operations &amp; BOH Management</b><br>• Back of House (BOH) audio handling<br>• Patching &amp; routing<br>• Signal flow management<br>• Live troubleshooting<br><b>Direct Mentorship</b><br>• Work under industry professionals<br>• Exposure to premium vendors &amp; global suppliers</pre></pre>',	'2026-02-17 21:35:48',	'2026-02-17 21:43:58');
